package com.yonlab.vision;
import android.content.Context;import org.json.*;import java.util.*;
/** Optional verified catalog annotations only; never invents reference boxes from detections. */
final class OneDetectionTruth {
 private OneDetectionTruth(){}
 static void apply(Context c,String demo,String inputSha,OneModelRunner.Result result){ExpansionTruth.apply(c,demo,inputSha,result);if(demo==null||demo.isEmpty()||!"COMPLETED".equals(result.state)||!("detect".equals(result.feature)||"flow".equals(result.feature)))return;
  try{DemoStore.Item item=DemoStore.find(c,demo);if(item==null||!item.sha256.equals(inputSha)){result.metrics.put("detectionEvaluationState","REFERENCE_INPUT_MISMATCH");return;}Object value=DemoStore.class.getMethod("detectionTruth",Context.class,String.class).invoke(null,c,demo);if(!(value instanceof String)||((String)value).isEmpty())return;JSONObject reference=new JSONObject((String)value);if(!reference.optBoolean("verified")||!"NORMALIZED_XYXY".equals(reference.optString("coordinateSpace")))return;JSONArray truth=reference.getJSONArray("objects"),pred=result.metrics.optJSONArray("detections");if(pred==null||truth.length()>1000||pred.length()>1000)return;List<String> canonical=new ArrayList<>();OneObjectEngine.read(c,"one/models/coco80-labels.txt",canonical);Map<String,Integer> labels=new LinkedHashMap<>();float[][] expected=new float[truth.length()][5],actual=new float[pred.length()][6];for(int i=0;i<truth.length();i++){JSONObject b=truth.getJSONObject(i);String label=b.optString("canonicalLabel",b.optString("label",""));if(b.has("canonicalLabel")&&b.has("label")&&!b.getString("canonicalLabel").equals(b.getString("label")))throw new IllegalArgumentException("ambiguous truth class");if(!canonical.contains(label))throw new IllegalArgumentException("noncanonical class");if(!labels.containsKey(label))labels.put(label,labels.size());expected[i]=new float[]{(float)b.getDouble("left"),(float)b.getDouble("top"),(float)b.getDouble("right"),(float)b.getDouble("bottom"),labels.get(label)};}for(int i=0;i<pred.length();i++){JSONObject b=pred.getJSONObject(i);String label=b.getString("label");if(!canonical.contains(label))throw new IllegalArgumentException("noncanonical class");if(!labels.containsKey(label))labels.put(label,labels.size());actual[i]=new float[]{(float)b.getDouble("left"),(float)b.getDouble("top"),(float)b.getDouble("right"),(float)b.getDouble("bottom"),(float)b.getDouble("score"),labels.get(label)};}
   long[] counts=OneDetectionEval.evaluate(actual,expected,.5f);double tp=counts[0],fp=counts[1],fn=counts[2];JSONObject metrics=new JSONObject().put("scope","ONE_VERIFIED_IMAGE_NOT_DATASET_MAP").put("iouThreshold",.5).put("TP",counts[0]).put("FP",counts[1]).put("FN",counts[2]).put("precision",tp+fp==0?JSONObject.NULL:tp/(tp+fp)).put("recall",tp+fn==0?JSONObject.NULL:tp/(tp+fn)).put("f1",2*tp+fp+fn==0?JSONObject.NULL:2*tp/(2*tp+fp+fn));result.metrics.put("verifiedDetectionEvaluation",metrics);result.detail+=(result.detail.isEmpty()?"":"\n")+"정답 상자 IoU≥0.5 · TP "+counts[0]+" / FP "+counts[1]+" / FN "+counts[2];
  }catch(ReflectiveOperationException missing){/* Catalog without verified box annotations: no quality score. */}catch(Exception invalid){try{result.metrics.put("detectionEvaluationState","INVALID_REFERENCE_OR_OUTPUT");}catch(JSONException ignored){}}
 }
}
